```tsx
import { useRef, type KeyboardEvent } from "react";
import "./AccentPicker.css";

export type AccentId = "blue" | "emerald" | "amber" | "rose";

interface AccentOption {
  readonly id: AccentId;
  readonly label: string;
}

const ACCENTS: readonly AccentOption[] = [
  { id: "blue", label: "Myelin blue" },
  { id: "emerald", label: "Emerald" },
  { id: "amber", label: "Amber" },
  { id: "rose", label: "Rose" },
];

export interface AccentPickerProps {
  value: AccentId;
  onChange: (value: AccentId) => void;
}

export function AccentPicker({ value, onChange }: AccentPickerProps) {
  const itemRefs = useRef<Array<HTMLButtonElement | null>>([]);

  const selectedIndex = Math.max(
    0,
    ACCENTS.findIndex((accent) => accent.id === value),
  );

  function selectAt(index: number): void {
    const next = ACCENTS[index];
    if (next === undefined) {
      return;
    }
    onChange(next.id);
    itemRefs.current[index]?.focus();
  }

  function handleKeyDown(event: KeyboardEvent<HTMLButtonElement>, index: number): void {
    const last = ACCENTS.length - 1;
    let target: number;

    switch (event.key) {
      case "ArrowRight":
      case "ArrowDown":
        target = index === last ? 0 : index + 1;
        break;
      case "ArrowLeft":
      case "ArrowUp":
        target = index === 0 ? last : index - 1;
        break;
      case "Home":
        target = 0;
        break;
      case "End":
        target = last;
        break;
      default:
        return;
    }

    event.preventDefault();
    selectAt(target);
  }

  return (
    <div role="radiogroup" aria-label="Accent colour" className="accent-picker">
      {ACCENTS.map((accent, index) => {
        const checked = accent.id === value;

        return (
          <button
            key={accent.id}
            ref={(element) => {
              itemRefs.current[index] = element;
            }}
            type="button"
            role="radio"
            aria-checked={checked}
            tabIndex={index === selectedIndex ? 0 : -1}
            data-accent={accent.id}
            className={[
              "accent-picker__option",
              checked ? "accent-picker__option--selected" : "",
            ]
              .filter(Boolean)
              .join(" ")}
            onClick={() => onChange(accent.id)}
            onKeyDown={(event) => handleKeyDown(event, index)}
          >
            <span className="accent-picker__swatch" aria-hidden="true" />
            <span className="accent-picker__label">{accent.label}</span>
            {checked && <span className="accent-picker__check" aria-hidden="true" />}
          </button>
        );
      })}
    </div>
  );
}
