 * --swatch and overridden for night so they keep contrast on dark surfaces.
 */

.accent-picker {
  --picker-surface: #ffffff;
  --picker-surface-hover: #f1f5f9;
  --picker-border: #cbd5e1;
  --picker-text: #0f172a;
  --picker-text-muted: #475569;
  --picker-selected-border: #0f172a;
  --picker-focus: #2563eb;
  --picker-check: #0f172a;

  --swatch-blue: #3b82f6;
  --swatch-emerald: #10b981;
  --swatch-amber: #f59e0b;
  --swatch-rose: #f43f5e;

  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.5rem;
  color: var(--picker-text);
}

[data-theme="night"] .accent-picker {
  --picker-surface: #111827;
  --picker-surface-hover: #1f2937;
  --picker-border: #334155;
  --picker-text: #e2e8f0;
  --picker-text-muted: #94a3b8;
  --picker-selected-border: #e2e8f0;
  --picker-focus: #93c5fd;
  --picker-check: #e2e8f0;

  --swatch-blue: #60a5fa;
  --swatch-emerald: #34d399;
  --swatch-amber: #fbbf24;
  --swatch-rose: #fb7185;
}

.accent-picker__option {
  display: flex;
  align-items: center;
  gap: 0.625rem;
  width: 100%;
  min-height: 2.75rem;
  padding: 0.5rem 0.75rem;
  margin: 0;
  border: 1px solid var(--picker-border);
  border-radius: 0.625rem;
  background: var(--picker-surface);
  color: var(--picker-text);
  font: inherit;
  font-size: 0.9375rem;
  text-align: left;
  cursor: pointer;
  transition:
    background-color 160ms ease,
    border-color 160ms ease;
}

.accent-picker__option:hover {
  background: var(--picker-surface-hover);
}

.accent-picker__option:focus {
  outline: none;
}

.accent-picker__option:focus-visible {
  outline: 2px solid var(--picker-focus);
  outline-offset: 2px;
}

.accent-picker__option--selected {
  border-color: var(--picker-selected-border);
  box-shadow: inset 0 0 0 1px var(--picker-selected-border);
}

.accent-picker__option[data-accent="blue"] {
  --swatch: var(--swatch-blue);
}

.accent-picker__option[data-accent="emerald"] {
  --swatch: var(--swatch-emerald);
}

.accent-picker__option[data-accent="amber"] {
  --swatch: var(--swatch-amber);
}

.accent-picker__option[data-accent="rose"] {
  --swatch: var(--swatch-rose);
}

.accent-picker__swatch {
  flex: 0 0 auto;
  width: 1.125rem;
  height: 1.125rem;
  border-radius: 999px;
  background: var(--swatch);
  box-shadow: inset 0 0 0 1px rgba(15, 23, 42, 0.12);
}

[data-theme="night"] .accent-picker__swatch {
  box-shadow: inset 0 0 0 1px rgba(226, 232, 240, 0.16);
}

.accent-picker__label {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.accent-picker__check {
  flex: 0 0 auto;
  position: relative;
  width: 0.875rem;
  height: 0.875rem;
}

.accent-picker__check::after {
  content: "";
  position: absolute;
  left: 0.2rem;
  top: 0.05rem;
  width: 0.3rem;
  height: 0.6rem;
  border: solid var(--picker-check);
  border-width: 0 2px 2px 0;
  transform: rotate(45deg);
}

@media (max-width: 22rem) {
  .accent-picker {
    grid-template-columns: minmax(0, 1fr);
  }
}

@media (prefers-reduced-motion: reduce) {
  .accent-picker__option {
    transition: none;
  }
}
